function [b0, tilt] = dipole()
%DIPOLE  The dipole strength B0 = sqrt(g10^2 + g11^2 + h11^2) and its tilt from the spin axis, from the degree-1 coefficients of the
%   IGRF-14 table at the epoch IGRF14_DEGREE1 states (its first value, 2025.0).
%   returns b0: real[T] (passed in kg/(s^2 A))
%   returns tilt: real[rad] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    b0 = 0;
    tilt = 0;
    D__IGRF14_DEGREE1 = asils.relations.igrf14dipole.IGRF14_DEGREE1();
    g10 = (D__IGRF14_DEGREE1(2) * 1e-9);
    g11 = (D__IGRF14_DEGREE1(3) * 1e-9);
    h11 = (D__IGRF14_DEGREE1(4) * 1e-9);
    h__0 = (((g10 * g10) + (g11 * g11)) + (h11 * h11));
    if h__0 < 0, h__0 = NaN; else, h__0 = sqrt(h__0); end
    b0 = h__0;
    h__1 = acos(((-(g10)) / b0));
    if ~isreal(h__1), h__1 = NaN; end
    tilt = h__1;
end
